package com.tekwatt.ocpp.controller;import com.tekwatt.ocpp.service.ConnectionRegistry;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;@RestController@RequestMapping("/api/v1/ocpp/connections")public class OcppConnectionController{private final ConnectionRegistry registry;public OcppConnectionController(ConnectionRegistry r){registry=r;}@GetMapping List<ConnectionRegistry.ConnectionInfo>all(){return registry.all();}@GetMapping("/{stationId}")ConnectionRegistry.ConnectionInfo get(@PathVariable String stationId){return registry.get(stationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Charger is not connected"));}}
